1	//! Asking a checker for the component a session was just asked about (ADR 0022).
2	//!
3	//! The structural answer is always computed first and is a complete answer on its own. With a [`SemanticProvider`]
4	//! attached, [`SemanticHook::refine`] asks the checker for exactly that component, waits a bounded time, and merges
5	//! its props over the structural ones. A checker that is slower than the budget leaves the structural answer in
6	//! place, and its late answer is kept for the next request of the same, unedited component.
7	//!
8	//! There is one request in flight per component and version of its file: a caller that finds one waits on it instead
9	//! of asking again, and a caller raises a request it joins to its own class, so a story asked while its own prefetch
10	//! runs is answered when the prefetch is.
11	//!
12	//! A request nobody waits for is cancelled when its answer would not be read: an edit superseded the revision it was
13	//! asked at ([`SemanticHook::invalidate`]), or the client no longer shows its component ([`SemanticHook::cancel`]).
14	//! A checker drops it before converting it; one already converting it finishes.
15	//!
16	//! An answer describes the component's props as the checker read them, which depends on every file the component
17	//! imports, not only its own. So the session drops every answer when any source file changes
18	//! ([`SemanticHook::invalidate`]), and an answer that was still on its way then is neither kept nor joined. The same
19	//! call tells the checker which files changed, since a warm one answers from what it read before (ADR 0026 S6).
20	
21	use std::hash::{Hash, Hasher};
22	use std::sync::{Arc, Condvar, Mutex, PoisonError};
23	use std::time::Duration;
24	
25	use rustc_hash::{FxHashMap, FxHashSet, FxHasher};
26	
27	use super::ComponentAnswer;
28	use crate::pipeline::HtmlAttributeMode;
29	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
30	use crate::types::options::CollapseContext;
31	use crate::types::semantic::{
32	    Delivery, Layering, MergedProps, Priority, PropInterner, SemanticComponent, SemanticFallback, SemanticOutcome,
33	    SemanticProp, SemanticProvider, SemanticTarget, SharedPriority, SourceChange, Superseding, drop_superseded,
34	    merge_semantic_props, unread_diagnostic,
35	};
36	
37	/// What one request of the checker made of a component: the component it found, if any, and what the checker said
38	/// about the request itself (an edit it was not told about, why a component kept its structural result). Both are the
39	/// answer, so a late answer, a joined one and every request the cache serves it to carry both.
40	#[derive(Clone, Default)]
41	struct Answered {
42	    component: Option<Arc<SemanticComponent>>,
43	    diagnostics: Vec<Diagnostic>,
44	}
45	
46	/// What became of one request to the checker, for every caller that waited on it.
47	#[derive(Clone)]
48	enum Settled {
49	    /// The checker answered for the component: kept for the next request.
50	    Answered(Answered),
51	    /// The checker answered nothing: it was unavailable, timed out or crashed. The structural props stand, with what
52	    /// the checker said, for the callers of this request only. Never kept: a checker that recovers answers the next
53	    /// request.
54	    Degraded(Vec<Diagnostic>),
55	    /// The checker stopped without answering.
56	    Stopped,
57	    /// The request was cancelled before the checker converted it ([`SharedPriority::cancel`]): not an answer, and not
58	    /// a checker that stopped, so a caller reads it as one still on its way.
59	    Cancelled,
60	}
61	
62	/// A request in flight. Every caller for the same component and version of its file waits on it instead of asking the
63	/// checker again.
64	struct Pending {
65	    /// What the checker answers it at; a caller someone is waiting for raises it on joining.
66	    priority: SharedPriority,
67	    settled: Mutex<Option<Settled>>,
68	    ready: Condvar,
69	}
70	
71	impl Pending {
72	    fn new(priority: Priority) -> Self {
73	        Self { priority: SharedPriority::new(priority), settled: Mutex::new(None), ready: Condvar::new() }
74	    }
75	
76	    fn settle(&self, settled: Settled) {
77	        *self.settled.lock().unwrap_or_else(PoisonError::into_inner) = Some(settled);
78	        self.ready.notify_all();
79	    }
80	
81	    /// What became of the request, if that is known within `wait`.
82	    fn wait(&self, wait: Duration) -> Option<Settled> {
83	        let settled = self.settled.lock().unwrap_or_else(PoisonError::into_inner);
84	        let (settled, _) = self
85	            .ready
86	            .wait_timeout_while(settled, wait, |settled| settled.is_none())
87	            .unwrap_or_else(PoisonError::into_inner);
88	        settled.clone()
89	    }
90	}
91	
92	/// What the checker said about one component at one version of its file, what it is still being asked, and the
93	/// generation they belong to.
94	#[derive(Default)]
95	struct AnswerCache {
96	    /// Raised by every [`SemanticHook::invalidate`]; an answer asked for under an earlier one is not stored.
97	    generation: u64,
98	    answers: FxHashMap<(String, u64), Answered>,
99	    /// Requests in flight under the current generation, by the same key as `answers`.
100	    pending: FxHashMap<(String, u64), Arc<Pending>>,
101	    /// The one copy of each prop the kept answers hold, for this generation.
102	    props: PropInterner,
103	}
104	
105	impl AnswerCache {
106	    /// `component` with each prop the one copy the kept answers share. A design system's components repeat the same
107	    /// props (Chakra's about a thousand style props each), and an answer kept with its own copies held about 6.7 MiB
108	    /// per Chakra component, so a session that answered a few hundred stories held gigabytes.
109	    fn shared(&self, component: Arc<SemanticComponent>) -> Arc<SemanticComponent> {
110	        let SemanticComponent { key, props, composes, whole } = Arc::unwrap_or_clone(component);
111	        let props = props.into_iter().map(|prop| self.props.share_arc(prop)).collect();
112	        Arc::new(SemanticComponent { key, props, composes, whole })
113	    }
114	}
115	
116	type Answers = Mutex<AnswerCache>;
117	
118	/// Where a request finds its answer.
119	enum Found {
120	    /// An answer kept from an earlier request.
121	    Cached(Answered),
122	    /// A request already in flight, to wait on.
123	    Joined(Arc<Pending>),
124	    /// Nothing: this caller asks, and others join it.
125	    Asking(Arc<Pending>),
126	}
127	
128	/// How long a request for a component the structural pass lists no props for waits for the checker, unless the session
129	/// says otherwise ([`SemanticHook::wait_empty`]): an empty answer is not worth showing early, and Chakra's `Button` takes
130	/// 0.4 to 0.8 s.
131	pub(crate) const DEFAULT_WAIT_EMPTY: Duration = Duration::from_secs(2);
132	
133	/// What an answer says when the checker had not answered within the wait and the structural props stand in for its.
134	const CHECKER_PENDING: &str = "the TypeScript checker has not answered yet; the structural props are used, and the \
135	                               checker's replace them on the next request";
136	
137	/// Whether `answer`'s props are the structural ones because the checker had not answered within the wait: asked again
138	/// once the checker has answered, and before any source file changes, the session answers with the checker's props.
139	/// The one place that decides it, for hosts that show an answer and replace it later.
140	pub fn awaits_checker(answer: &ComponentAnswer) -> bool {
141	    answer.diagnostics.iter().any(|diagnostic| {
142	        diagnostic.code == DiagnosticCode::SemanticBackend
143	            && diagnostic.severity == DiagnosticSeverity::Info
144	            && diagnostic.message == CHECKER_PENDING
145	    })
146	}
147	
148	pub(crate) struct SemanticHook {
149	    provider: Arc<dyn SemanticProvider>,
150	    /// How long a request waits for the checker before it takes the structural answer.
151	    wait: Duration,
152	    /// How long it waits instead when the structural answer has no props; never less than `wait`.
153	    wait_empty: Duration,
154	    answers: Arc<Answers>,
155	}
156	
157	impl SemanticHook {
158	    pub(crate) fn new(provider: Arc<dyn SemanticProvider>, wait: Duration) -> Self {
159	        Self { provider, wait, wait_empty: DEFAULT_WAIT_EMPTY, answers: Arc::new(Mutex::new(AnswerCache::default())) }
160	    }
161	
162	    /// Sets how long a request for a component with no structural props waits for the checker. A wait at most `wait`
163	    /// gives such a component the same wait as every other.
164	    pub(crate) fn wait_empty(&mut self, wait_empty: Duration) {
165	        self.wait_empty = wait_empty;
166	    }
167	
168	    /// The wait for `answer`. Nobody waits for a neighbour or background request: its answer is kept for the request
169	    /// that follows.
170	    /// Someone does for an interactive one, and longer when the structural pass found no props, since there is nothing
171	    /// to show before the checker answers. Any prop, even a degraded one, is an answer worth showing at the short wait.
172	    fn wait_for(&self, answer: &ComponentAnswer, priority: Priority) -> Duration {
173	        match (priority, answer.entry.props.is_empty()) {
174	            (Priority::Neighbour | Priority::Background, _) => Duration::ZERO,
175	            (Priority::Interactive, true) => self.wait_empty.max(self.wait),
176	            (Priority::Interactive, false) => self.wait,
177	        }
178	    }
179	
180	    /// Forget every answer, refuse the ones still being waited for, and tell the checker what changed: a source file
181	    /// changed, and the checker's props for any component can depend on it. The next request of each component asks
182	    /// the checker again, after it has been told, rather than joining a request asked before the change. A request
183	    /// nobody waits for is cancelled: its answer, of the superseded revision, would not be kept, so a checker that has
184	    /// not started it drops it. One someone waits for is still answered, after the change.
185	    pub(crate) fn invalidate(&self, change: SourceChange) {
186	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
187	        cache.generation += 1;
188	        cache.answers.clear();
189	        for pending in cache.pending.values() {
190	            pending.priority.cancel();
191	        }
192	        cache.pending.clear();
193	        cache.props = PropInterner::default();
194	        self.provider.changed(change);
195	    }
196	
197	    /// Cancels the requests in flight for `keys` that nobody waits for: the client no longer shows those components,
198	    /// so a checker that has not started them drops them. A later request asks again rather than joining a cancelled
199	    /// one; a request someone waits for, or one the checker is already converting, stays registered, so a later request
200	    /// joins it, and is answered (and kept) as before.
201	    pub(crate) fn cancel(&self, keys: &[String]) {
202	        let keys: FxHashSet<&str> = keys.iter().map(String::as_str).collect();
203	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
204	        cache.pending.retain(|(key, _), pending| !(keys.contains(key.as_str()) && pending.priority.cancel()));
205	    }
206	
207	    /// `answer` with the checker's props, when it has them within the wait `priority` gives it.
208	    pub(crate) fn refine(
209	        &self,
210	        mut answer: ComponentAnswer,
211	        mode: HtmlAttributeMode,
212	        cx: CollapseContext,
213	        priority: Priority,
214	    ) -> ComponentAnswer {
215	        let mode = crate::react_types::react_attribute_mode(mode, crate::react_types::expanded(&answer.entry, cx.mode));
216	        // The checker converts only the props this merge keeps, decided from the structural answer and `cx`: an answer
217	        // is kept and joined for those too, so another structural answer is never merged with props left unconverted.
218	        let layering = Layering::of(&answer.entry, cx);
219	        let stamp = std::fs::read(&answer.entry.file_path).map(|bytes| {
220	            let mut hasher = FxHasher::default();
221	            bytes.hash(&mut hasher);
222	            layering.hash(&mut hasher);
223	            hasher.finish()
224	        });
225	        let cache_key = stamp.ok().map(|stamp| (answer.key.clone(), stamp));
226	
227	        let (found, generation) = self.find(cache_key.as_ref(), priority);
228	        let pending = match found {
229	            Found::Cached(cached) => {
230	                self.apply(&mut answer, cached, mode, cx);
231	                return answer;
232	            }
233	            Found::Joined(pending) => pending,
234	            Found::Asking(pending) => {
235	                self.ask(target_of(&answer, mode, layering), &pending, cache_key, generation);
236	                pending
237	            }
238	        };
239	
240	        match pending.wait(self.wait_for(&answer, priority)) {
241	            Some(Settled::Answered(answered)) => self.apply(&mut answer, answered, mode, cx),
242	            Some(Settled::Degraded(diagnostics)) => answer.diagnostics.extend(diagnostics),
243	            Some(Settled::Stopped) => {
244	                let mut stopped = Diagnostic::new(
245	                    DiagnosticSeverity::Warning,
246	                    DiagnosticCode::SemanticBackend,
247	                    "the TypeScript checker stopped without answering; the structural props are used",
248	                );
249	                stopped.affects = vec![answer.key.clone()];
250	                answer.diagnostics.push(stopped);
251	            }
252	            Some(Settled::Cancelled) | None => {
253	                let mut pending =
254	                    Diagnostic::new(DiagnosticSeverity::Info, DiagnosticCode::SemanticBackend, CHECKER_PENDING);
255	                pending.affects = vec![answer.key.clone()];
256	                answer.diagnostics.push(pending);
257	            }
258	        }
259	        answer
260	    }
261	
262	    /// The kept answer for `key`, else the request in flight for it (raised to `priority` when that goes first), else a
263	    /// new request this caller makes, registered so the next caller joins it. One lock, so two callers never both ask.
264	    /// A file that could not be read has no key: its request is neither kept nor joined.
265	    fn find(&self, key: Option<&(String, u64)>, priority: Priority) -> (Found, u64) {
266	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
267	        let generation = cache.generation;
268	        if let Some(key) = key {
269	            if let Some(cached) = cache.answers.get(key) {
270	                return (Found::Cached(cached.clone()), generation);
271	            }
272	            if let Some(pending) = cache.pending.get(key) {
273	                pending.priority.raise_to(priority);
274	                return (Found::Joined(pending.clone()), generation);
275	            }
276	        }
277	        let pending = Arc::new(Pending::new(priority));
278	        if let Some(key) = key {
279	            cache.pending.insert(key.clone(), pending.clone());
280	        }
281	        (Found::Asking(pending), generation)
282	    }
283	
284	    /// Asks the checker about `target`. Its outcome settles `pending` for every caller waiting on it and, when it
285	    /// answers for the component, is kept for the next request, unless the cache was invalidated since `generation`.
286	    /// Called without the cache's lock, since a provider may deliver at once.
287	    fn ask(&self, target: SemanticTarget, pending: &Arc<Pending>, key: Option<(String, u64)>, generation: u64) {
288	        let answers = self.answers.clone();
289	        let asked = target.key.clone();
290	        let settling = pending.clone();
291	        let delivery = Delivery::new(move |outcome| {
292	            let mut settled = match outcome {
293	                Some(outcome) => read_outcome(&asked, outcome),
294	                None if settling.priority.is_cancelled() => Settled::Cancelled,
295	                None => Settled::Stopped,
296	            };
297	            if let Some(key) = key {
298	                let mut cache = answers.lock().unwrap_or_else(PoisonError::into_inner);
299	                if cache.pending.get(&key).is_some_and(|registered| Arc::ptr_eq(registered, &settling)) {
300	                    cache.pending.remove(&key);
301	                }
302	                if let Settled::Answered(answered) = &mut settled
303	                    && cache.generation == generation
304	                {
305	                    answered.component = answered.component.take().map(|component| cache.shared(component));
306	                    cache.answers.insert(key, answered.clone());
307	                }
308	            }
309	            settling.settle(settled);
310	        });
311	        self.provider.request_at(vec![target], pending.priority.clone(), delivery);
312	    }
313	
314	    /// Merges what the checker made of the component into `answer`: its props, if it found the component, then what it
315	    /// said about the request. The structural diagnostics its props supersede go first, so the checker's are never
316	    /// read as structural.
317	    fn apply(&self, answer: &mut ComponentAnswer, answered: Answered, mode: HtmlAttributeMode, cx: CollapseContext) {
318	        let Answered { component, diagnostics } = answered;
319	        let Some(component) = component else {
320	            answer.diagnostics.extend(diagnostics);
321	            return;
322	        };
323	        let structural = answer.entry.props.clone();
324	        let visible = crate::react_types::visible_rows(&answer.entry);
325	        let used: Vec<&Arc<SemanticProp>> = component
326	            .props
327	            .iter()
328	            .filter(|prop| crate::react_types::checker_prop_kept(mode, &prop.name, prop.react_declared, &visible))
329	            .collect();
330	        // The props of a collapsed source are its layer's, not listed again.
331	        let (used, notable) =
332	            crate::types::semantic::layer_checker_props(&mut answer.entry, used, &component.whole, cx);
333	        // A structural prop the checker did not return keeps its structural type, opaque or not, and a structural
334	        // diagnostic naming the component may be about it.
335	        let structural_left = structural
336	            .iter()
337	            .any(|(name, prop)| prop.prop_type.holds_opaque() && !used.iter().any(|answered| answered.name == *name));
338	        let MergedProps { kept, unread, diagnostics: syntax } = merge_semantic_props(
339	            &mut answer.entry,
340	            used.into_iter(),
341	            component.composes.as_deref(),
342	            &mut FxHashMap::default(),
343	        );
344	        crate::types::semantic::move_notable(&mut answer.entry, &notable);
345	        crate::types::semantic::listed_props_leave_layers(&mut answer.entry, true);
346	        crate::relevance::narrow(&mut answer.entry);
347	        let superseding = Superseding::new(&answer.key, &answer.entry, structural_left);
348	        drop_superseded(&mut answer.diagnostics, &[superseding]);
349	        answer.diagnostics.extend(diagnostics);
350	        let mut provenance = Diagnostic::new(
351	            DiagnosticSeverity::Info,
352	            DiagnosticCode::SemanticBackend,
353	            match kept {
354	                0 => "1 component(s) resolved by the TypeScript checker".to_string(),
355	                kept => format!(
356	                    "1 component(s) resolved by the TypeScript checker; {kept} prop(s) it did not report keep their \
357	                     structural type"
358	                ),
359	            },
360	        );
361	        provenance.affects = vec![answer.key.clone()];
362	        answer.diagnostics.push(provenance);
363	        answer.diagnostics.extend(syntax);
364	        if unread > 0 {
365	            answer.diagnostics.push(unread_diagnostic(unread, vec![answer.key.clone()]));
366	        }
367	    }
368	}
