370	/// What the checker is asked about `answer`'s component: its props under `mode`, converted only where the merge with
371	/// `layering` keeps them.
372	fn target_of(answer: &ComponentAnswer, mode: HtmlAttributeMode, layering: Layering) -> SemanticTarget {
373	    SemanticTarget {
374	        key: answer.key.clone(),
375	        file_path: answer.entry.file_path.clone(),
376	        display_name: answer.entry.display_name.clone(),
377	        exports: answer.entry.exports.clone(),
378	        described: answer
379	            .entry
380	            .props
381	            .values()
382	            .filter(|prop| !prop.description.is_empty())
383	            .map(|prop| prop.name.clone())
384	            .collect(),
385	        react_wanted: crate::react_types::react_props_wanted_for(mode, &answer.entry),
386	        layering: Some(layering),
387	    }
388	}
