390	/// The outcome read for the component whose output key is `asked`, with every diagnostic it carries: a warning that
391	/// came with an answer (an edit the checker was not told about) is about this request, and a fallback's reason says why
392	/// the component kept its structural result. An outcome with no component and no fallback at all (the checker was
393	/// unavailable, timed out or crashed) answers nothing: it is [`Settled::Degraded`], whatever it says. An answer or
394	/// fallback for another key is not this component's.
395	fn read_outcome(asked: &str, outcome: SemanticOutcome) -> Settled {
396	    let SemanticOutcome { components, fallbacks, diagnostics: reported } = outcome;
397	    let unavailable = components.is_empty() && fallbacks.is_empty();
398	    let mut diagnostics: Vec<Diagnostic> = reported
399	        .into_iter()
400	        .map(|mut diagnostic| {
401	            diagnostic.affects = vec![asked.to_owned()];
402	            diagnostic
403	        })
404	        .collect();
405	    if unavailable {
406	        return Settled::Degraded(diagnostics);
407	    }
408	    let component = components.into_iter().find(|found| found.key == asked).map(Arc::new);
409	    for SemanticFallback { key, reason } in fallbacks {
410	        if key != asked {
411	            continue;
412	        }
413	        let mut info = Diagnostic::new(
414	            DiagnosticSeverity::Info,
415	            DiagnosticCode::SemanticBackend,
416	            format!("1 component(s) kept their structural result: {reason}"),
417	        );
418	        info.affects = vec![key];
419	        diagnostics.push(info);
420	    }
421	    Settled::Answered(Answered { component, diagnostics })
422	}
