525	    /// `parse`, with the text of `file` when the caller has already read it, and [`Unreadable`] when it exists but
526	    /// could not be read. That is not kept, in this load or its layer: the next caller reads the file again.
527	    fn parse_source(&self, file: &Utf8Path, source: Option<String>) -> Result<Option<Arc<SourceData>>, Unreadable> {
528	        if let Some(found) = self.parent.and_then(|parent| parent.parsed_data(file.as_str())) {
529	            return Ok(found.clone());
530	        }
531	        let cell = self.parsed.entry(PathKey::from(file)).or_default().clone();
532	        if let Some(found) = cell.get() {
533	            return Ok(found.clone());
534	        }
535	        let source = match source {
536	            Some(source) => Some(source),
537	            None => self.read_text(file)?,
538	        };
539	        Ok(cell
540	            .get_or_init(|| {
541	                let source = source?;
542	                let mut data = crate::extractor::parse_file(file, &source);
543	                // Problems inside a package's types are not the project's; an unresolved demand is reported instead.
544	                data.diagnostics.clear();
545	                Some(Arc::new(data))
546	            })
547	            .clone())
