550	    /// Resolve `specifier` as imported by `from_file`, the way the resolver will.
551	    fn resolve(&self, from_file: &Utf8Path, specifier: &str) -> Result<Utf8PathBuf, Unresolved> {
552	        let dir = from_file.parent().map_or("", Utf8Path::as_str);
553	        let key = (Box::from(dir), Box::from(specifier));
554	        if let Some(found) = self.resolutions.get(&key) {
555	            return found.clone();
556	        }
557	        if let Some(found) = self.parent.and_then(|parent| parent.resolution(&key)) {
558	            return found.clone();
559	        }
560	        let result = match crate::resolver::resolve_module_with(
561	            &self.resolvers.main,
562	            &self.resolvers.types_first,
563	            specifier,
564	            from_file,
565	        ) {
566	            ModuleResolution::PackageTypes(path) => Ok(path),
567	            ModuleResolution::File(path) if is_typescript(&path) => Ok(path),
568	            ModuleResolution::File(_) => Err(Unresolved::NoTypes),
569	            ModuleResolution::Unresolved(_) => Err(Unresolved::Unresolvable),
570	        };
571	        // An unresolved import is not kept in the index, so asking again is not new knowledge.
572	        if result.is_ok() {
573	            self.learn(Utf8Path::new(dir));
574	        }
575	        self.resolutions.insert(key, result.clone());
576	        result
577	    }
