588	    /// The `(file, name)` declaring `name` as exported from `module`.
589	    fn find_export(&self, module: &Utf8Path, name: &str) -> Option<(Utf8PathBuf, CompactString)> {
590	        self.find_export_in(module, name, &mut FxHashSet::default(), &mut false)
