593	    /// `find_export` within one walk. A lookup that met a module already on the walk (a re-export cycle) is `cut`: its
594	    /// answer depends on where the walk entered the cycle, so it is returned but not kept, and the cut propagates to
595	    /// every lookup that relied on it. Kept answers are therefore the same in any order and on any thread.
596	    fn find_export_in(
597	        &self,
598	        module: &Utf8Path,
599	        name: &str,
600	        visited: &mut FxHashSet<(PathKey, CompactString)>,
601	        cut: &mut bool,
602	    ) -> Option<(Utf8PathBuf, CompactString)> {
603	        let key = (PathKey::from(module), CompactString::from(name));
604	        if let Some(found) = self.exports.get(&key) {
605	            return found.clone();
606	        }
607	        if let Some(found) = self.parent.and_then(|parent| parent.export_entry(&key)) {
608	            return found.clone();
609	        }
610	        if !visited.insert(key.clone()) {
611	            *cut = true;
612	            return None;
613	        }
614	        let mut own_cut = false;
615	        let found = self.find_export_uncached(module, name, visited, &mut own_cut);
616	        visited.remove(&key);
617	        if own_cut {
618	            *cut = true;
619	        } else {
620	            if let Some(dir) = module.parent() {
621	                self.learn(dir);
622	            }
623	            self.exports.insert(key, found.clone());
624	        }
625	        found
626	    }
