628	    fn find_export_uncached(
629	        &self,
630	        module: &Utf8Path,
631	        name: &str,
632	        visited: &mut FxHashSet<(PathKey, CompactString)>,
633	        cut: &mut bool,
634	    ) -> Option<(Utf8PathBuf, CompactString)> {
635	        let data = match self.parse_source(module, None) {
636	            Ok(data) => data?,
637	            // What the module exports is unknown, not absent: the miss is returned but, like a cycle's, neither kept
638	            // nor persisted, so the next lookup or run reads the module again.
639	            Err(Unreadable) => {
640	                *cut = true;
641	                return None;
642	            }
643	        };
644	        if declares(&data, module, name) {
645	            return Some((module.to_owned(), CompactString::from(name)));
646	        }
647	        // A member of a value the module declares (`Primitive.div`): its declaration is the value's.
648	        if name.split_once('.').is_some_and(|(head, _)| declares(&data, module, head)) {
649	            return Some((module.to_owned(), CompactString::from(name)));
650	        }
651	        let (head, rest) = match name.split_once('.') {
652	            Some((head, rest)) => (head, Some(rest)),
653	            None => (name, None),
654	        };
655	        for export in &data.exports {
656	            match export {
657	                LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. } if local_name == head => {
658	                    // An explicit export shadows a wildcard one, so a hop that cannot be resolved leaves the name unanswered
659	                    // rather than to a later `export *`; `unresolved_cause` names the hop.
660	                    let Ok(target) = self.resolve(module, source_specifier) else { return None };
661	                    let next = match rest {
662	                        Some(rest) => format!("{source_name}.{rest}"),
663	                        None => source_name.clone(),
664	                    };
665	                    return self.find_export_in(&target, &next, visited, cut);
666	                }
667	                LexedExport::ReExportNamespace { namespace, source_specifier } if namespace == head => {
668	                    let Ok(target) = self.resolve(module, source_specifier) else { return None };
669	                    return self.find_export_in(&target, rest?, visited, cut);
670	                }
671	                // `export { DialogContent as Content }`, the way bundled typings (Radix's) name their parts.
672	                LexedExport::LocalDeclaration { name: exported, declared_as: Some(local), .. }
673	                    if exported == head && declares(&data, module, local) =>
674	                {
675	                    let name = match rest {
676	                        Some(rest) => format!("{local}.{rest}"),
677	                        None => local.clone(),
678	                    };
679	                    return Some((module.to_owned(), CompactString::from(name)));
680	                }
681	                _ => {}
682	            }
683	        }
684	        // A local export can name an imported binding (`import Image from './Image'; export default Image`).
685	        if let Some(local) = data.exports.iter().find_map(|export| match export {
686	            LexedExport::LocalDeclaration { name: exported, declared_as, .. } if exported == head => {
687	                Some(declared_as.as_deref().unwrap_or(head))
688	            }
689	            LexedExport::LocalDeclaration { .. }
690	            | LexedExport::ReExportNamed { .. }
691	            | LexedExport::ReExportAll { .. }
692	            | LexedExport::ReExportNamespace { .. } => None,
693	        }) {
694	            let reference = rest.map_or_else(|| local.to_owned(), |rest| format!("{local}.{rest}"));
695	            if let Some(demand) = imported_demand(module, &data.imports, &reference) {
696	                let target = self.resolve(module, &demand.specifier).ok()?;
697	                return self.find_export_in(&target, &demand.name, visited, cut);
698	            }
699	        }
700	        if head == "default" {
701	            return None;
702	        }
703	        for export in &data.exports {
704	            if let LexedExport::ReExportAll { source_specifier, .. } = export {
705	                let Ok(target) = self.resolve(module, source_specifier) else { continue };
706	                if let Some(found) = self.find_export_in(&target, name, visited, cut) {
707	                    return Some(found);
708	                }
709	            }
710	        }
711	        None
712	    }
