728	        if self.parent.is_some_and(|parent| parent.has_demand(&key)) || !self.demands.insert(key.clone()) {
729	            return;
730	        }
731	        if demand.name.is_empty() {
732	            self.module_demand(scope, &demand);
733	            return;
734	        }
735	        let module = match self.resolve(&demand.from, &demand.specifier) {
736	            Ok(module) => module,
737	            Err(reason) => {
738	                if !demand.name.is_empty() {
739	                    self.unresolved.insert(key, reason);
740	                }
741	                return;
742	            }
743	        };
744	        if self.in_project(&module) {
745	            return;
746	        }
747	        if Self::is_react(&module) {
