749	            let qualified = CompactString::from(format!("React.{}", demand.name));
750	            if self.parse(&module).is_some_and(|data| declares(&data, &module, &qualified)) {
751	                self.load_declaration(scope, module, qualified);
752	            }
753	            return;
754	        }
755	        match self.find_export(&module, &demand.name) {
756	            Some((file, name)) => self.load_declaration(scope, file, name),
757	            None => {
758	                let cause = self.unresolved_cause(&module, &demand.name).unwrap_or(Unresolved::NotExported);
759	                self.unresolved.insert(key, cause);
760	            }
761	        }
762	    }
