773	    fn unresolved_cause_in(
774	        &self,
775	        module: &Utf8Path,
776	        name: &str,
777	        visited: &mut FxHashSet<(PathKey, CompactString)>,
778	        star: &mut Option<Unresolved>,
779	    ) -> Option<Unresolved> {
780	        if !visited.insert((PathKey::from(module), CompactString::from(name))) {
781	            return None;
782	        }
783	        let data = self.parse(module)?;
784	        let (head, rest) = match name.split_once('.') {
785	            Some((head, rest)) => (head, Some(rest)),
786	            None => (name, None),
787	        };
788	        // The order `find_export_uncached` reads them in: an explicit export answers for its name and shadows every
789	        // wildcard, so a wildcard is looked into only when no explicit export names it.
790	        for star_pass in [false, true] {
791	            for export in &data.exports {
792	                let (specifier, next) = match export {
793	                    LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. }
794	                        if !star_pass && local_name == head =>
795	                    {
796	                        let next = rest.map_or_else(|| source_name.clone(), |rest| format!("{source_name}.{rest}"));
797	                        (source_specifier, next)
798	                    }
799	                    LexedExport::ReExportNamespace { namespace, source_specifier }
800	                        if !star_pass && namespace == head =>
801	                    {
802	                        (source_specifier, rest?.to_owned())
803	                    }
804	                    // `export *` never carries `default`, as `find_export_uncached` enforces.
805	                    LexedExport::ReExportAll { source_specifier, .. } if star_pass && head != "default" => {
806	                        (source_specifier, name.to_owned())
807	                    }
808	                    _ => continue,
809	                };
810	                match self.resolve(module, specifier) {
811	                    Err(cause) if star_pass => {
812	                        star.get_or_insert(cause);
813	                    }
814	                    Err(cause) => return Some(cause),
815	                    Ok(target) => {
816	                        let cause = self.unresolved_cause_in(&target, &next, visited, star);
817	                        if cause.is_some() || !star_pass {
818	                            return cause;
819	                        }
820	                    }
821	                }
822	            }
823	        }
824	        None
825	    }
