        found.sort();
        let own = module.parent().and_then(|dir| self.package_of(dir));
        let mut crossed: Vec<PackageStampRow> = seen
            .iter()
            .filter_map(|file| self.package_of(file.parent()?))
            .filter(|package| Some(package) != own.as_ref())
            .collect::<FxHashSet<_>>()
